/// <summary>
/// Manages fake shadow quads for 2.5D objects.
///
/// For each registered IShadowTarget, positions a shadow quad on the ground
/// plane below the target using a downward raycast.
///
/// MVP: logs the count of registered shadows. Actual quad rendering can be
/// added later.
/// </summary>
[DefaultExecutionOrder(-90)]
public class ShadowManager : MonoBehaviour
{
    private readonly List<IShadowTarget> _targets = new();

    /// <summary>Register a target for shadow rendering.</summary>
    public void Register(IShadowTarget target)
    {
        if (target == null) return;
        if (!_targets.Contains(target))
        {
            _targets.Add(target);
            Debug.Log($"[ShadowManager] Shadow registered. Total: {_targets.Count}");
        }
    }

    /// <summary>Unregister a target from shadow rendering.</summary>
    public void Unregister(IShadowTarget target)
    {
        if (target == null) return;
        _targets.Remove(target);
        Debug.Log($"[ShadowManager] Shadow unregistered. Total: {_targets.Count}");
    }

    private void LateUpdate()
    {
        // MVP: just log the count so we know it's running.
        // Actual shadow quad positioning/rendering comes later.
        if (_targets.Count > 0)
        {
            // Stub: future implementation will raycast down from each target
            // and position a shadow quad on the ground plane below.
        }
    }
}

