args.script:
using UnityEngine;
using Cinemachine;

var player = UnityEngine.Object.FindObjectOfType<SolarpunkCharacterController>().gameObject;

// Create a Cinemachine FreeLook camera
var vcObj = new GameObject("CM FreeLook");
var freeLook = vcObj.AddComponent<CinemachineFreeLook>();

// Follow and look at the player
freeLook.Follow = player.transform;
freeLook.LookAt = player.transform;

// Position the rig behind and above the player
vcObj.transform.position = new Vector3(0, 3, -6);

// Configure the FreeLook orbits
freeLook.m_Orbits = new CinemachineFreeLook.Orbit[]
{
    new CinemachineFreeLook.Orbit(4.5f, 1.5f),   // Top ring
    new CinemachineFreeLook.Orbit(3.0f, 3.0f),   // Middle ring  
    new CinemachineFreeLook.Orbit(1.2f, 4.0f),   // Bottom ring
};

// Set default binding mode
freeLook.m_BindingMode = CinemachineTransposer.BindingMode.SimpleFollowWithWorldUp;

// Set some reasonable defaults
freeLook.m_YAxis.Value = 0.5f;    // Start at middle
freeLook.m_YAxis.m_MaxSpeed = 2f;
freeLook.m_XAxis.m_MaxSpeed = 300f;
freeLook.m_YAxisRecentering.m_enabled = false;

// Lens settings
freeLook.m_Lens.FieldOfView = 40f;
freeLook.m_Lens.NearClipPlane = 0.1f;
freeLook.m_Lens.FarClipPlane = 1000f;

// Set the Game View camera
CinemachineBrain.SoloCamera = freeLook;

Debug.Log($"[Cinemachine] Created FreeLook camera following '{player.name}'");

