using UnityEngine;
using Cinemachine;

// Find or create a CinemachineBrain
var brain = Camera.main?.GetComponent<CinemachineBrain>();
if (brain == null)
{
    var mainCam = Camera.main?.gameObject;
    if (mainCam == null)
    {
        // Create a main camera
        mainCam = new GameObject("Main Camera");
        mainCam.AddComponent<Camera>();
        mainCam.tag = "MainCamera";
    }
    brain = mainCam.AddComponent<CinemachineBrain>();
    Debug.Log("[Cinemachine] Added CinemachineBrain to Main Camera");
}
else
{
    Debug.Log("[Cinemachine] Brain already exists on Main Camera");
}

// Log camera info
Debug.Log($"[Cinemachine] Main Camera pos: {Camera.main.transform.position}");
Debug.Log($"[Cinemachine] Main Camera FOV: {Camera.main.fieldOfView}");
Debug.Log($"[Cinemachine] Main Camera ortho: {Camera.main.orthographic}");

// Find the FreeLook
var freeLook = Object.FindObjectOfType<CinemachineFreeLook>();
if (freeLook != null)
{
    Debug.Log($"[Cinemachine] FreeLook Follow: {freeLook.Follow?.name ?? "null"}");
    Debug.Log($"[Cinemachine] FreeLook LookAt: {freeLook.LookAt?.name ?? "null"}");
    Debug.Log($"[Cinemachine] FreeLook pos: {freeLook.transform.position}");
}

