args.script:
using UnityEngine;
using Cinemachine;

var freeLook = Object.FindObjectOfType<CinemachineFreeLook>();
if (freeLook == null) { Debug.LogError("No FreeLook found"); return; }

var player = Object.FindObjectOfType<SolarpunkCharacterController>().gameObject;

// Reposition the FreeLook parent object to be behind and above the player
freeLook.transform.position = new Vector3(0, 4, -8);

// Reconfigure for a better 3rd-person follow camera
freeLook.m_Orbits = new CinemachineFreeLook.Orbit[]
{
    new CinemachineFreeLook.Orbit(6f, 2f),     // Top ring
    new CinemachineFreeLook.Orbit(4f, 4f),     // Middle ring
    new CinemachineFreeLook.Orbit(1.5f, 6f),   // Bottom ring
};

// Wider FOV
freeLook.m_Lens.FieldOfView = 50f;

// Set binding mode to world up for more natural orbiting
freeLook.m_BindingMode = CinemachineTransposer.BindingMode.SimpleFollowWithWorldUp;

// Start at middle orbit looking forward
freeLook.m_YAxis.Value = 0.5f;
freeLook.m_XAxis.Value = 0f;

// Damping for smooth follow
var topRig = freeLook.GetRig(0);
var midRig = freeLook.GetRig(1);
var botRig = freeLook.GetRig(2);

if (topRig != null) topRig.GetCinemachineComponent<CinemachineTransposer>().m_Damping = 1f;
if (midRig != null) midRig.GetCinemachineComponent<CinemachineTransposer>().m_Damping = 1f;
if (botRig != null) botRig.GetCinemachineComponent<CinemachineTransposer>().m_Damping = 1f;

Debug.Log($"[Cinemachine] Repositioned FreeLook - pos: {freeLook.transform.position}");

