using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using Flynn.Events;

/// <summary>
/// Manages floating HP bars above ResourceNodes. Subscribes to GameEventBus
/// for ResourceDamaged / ResourceDepleted and creates a lightweight world-space
/// Canvas + Slider per node on first hit. Bars auto-hide after a timeout and
/// are removed when the node is depleted.
///
/// One per scene under MANAGERS/UI. NOT a singleton — uses GameEventBus.Instance.
/// </summary>
public class ResourceHealthBarManager : MonoBehaviour
{
    [Header("Bar Appearance")]
    [Tooltip("World-space height offset above the node origin.")]
    [SerializeField] private float _heightOffset = 1.4f;

    [Tooltip("Width of the slider bar in world units.")]
    [SerializeField] private float _barWidth = 1.2f;

    [Tooltip("Height of the slider bar in world units.")]
    [SerializeField] private float _barHeight = 0.12f;

    [Header("Timing")]
    [Tooltip("Seconds to keep the bar visible after the last hit.")]
    [SerializeField] private float _displayDuration = 3f;

    [Tooltip("Seconds for the fade-out animation.")]
    [SerializeField] private float _fadeDuration = 0.5f;

    // ── Internal state ─────────────────────────────────────────────────────

    private readonly Dictionary<ResourceNode, HealthBarEntry> _bars = new();

    private struct HealthBarEntry
    {
        public GameObject Root;
        public Canvas Canvas;
        public Slider Slider;
        public CanvasGroup Group;
        public float HideTime;
        public bool Fading;
    }

    // ── Unity messages ──────────────────────────────────────────────────────

    private void OnEnable()
    {
        GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
    }

    private void OnDisable()
    {
        if (GameEventBus.Instance == null) return;
        GameEventBus.Instance.Unsubscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Unsubscribe<ResourceDepleted>(OnResourceDepleted);
    }

    private void LateUpdate()
    {
        float now = Time.time;
        List<ResourceNode> toRemove = null;

        foreach (var kvp in _bars)
        {
            var entry = kvp.Value;
            if (entry.Root == null)
            {
                if (toRemove == null) toRemove = new List<ResourceNode>();
                toRemove.Add(kvp.Key);
                continue;
            }

            // Position the bar above the node
            Transform nodeT = kvp.Key.transform;
            entry.Root.transform.position = nodeT.position + Vector3.up * _heightOffset;

            // Billboard — face the camera
            if (Camera.main != null)
                entry.Root.transform.rotation = Camera.main.transform.rotation;

            // Auto-hide after display duration
            if (!entry.Fading && now >= entry.HideTime)
            {
                entry.Fading = true;
            }

            // Fade out
            if (entry.Fading)
            {
                float elapsed = now - entry.HideTime;
                float alpha = 1f - Mathf.Clamp01(elapsed / _fadeDuration);
                entry.Group.alpha = alpha;

                if (alpha <= 0f)
                {
                    entry.Root.SetActive(false);
                }
            }
        }

        // Clean up destroyed nodes
        if (toRemove != null)
        {
            foreach (var node in toRemove)
            {
                var entry = _bars[node];
                if (entry.Root != null) Destroy(entry.Root);
                _bars.Remove(node);
            }
        }
    }

    // ── Event handlers ──────────────────────────────────────────────────────

    private void OnResourceDamaged(ResourceDamaged evt)
    {
        if (evt.Node == null) return;

        if (!_bars.TryGetValue(evt.Node, out var entry) || entry.Root == null)
        {
            entry = CreateBar(evt.Node);
            _bars[evt.Node] = entry;
        }

        // Update fill
        float ratio = evt.Node.MaxHealth > 0 ? (float)evt.RemainingHp / evt.Node.MaxHealth : 0f;
        entry.Slider.value = ratio;

        // Show and reset timer
        entry.Root.SetActive(true);
        entry.Group.alpha = 1f;
        entry.Fading = false;
        entry.HideTime = Time.time + _displayDuration;

        _bars[evt.Node] = entry;
    }

    private void OnResourceDepleted(ResourceDepleted evt)
    {
        if (evt.Node == null) return;
        if (!_bars.TryGetValue(evt.Node, out var entry)) return;

        // Snap to zero and force a quick fade
        entry.Slider.value = 0f;
        entry.Fading = true;
        entry.HideTime = Time.time;
        _bars[evt.Node] = entry;
    }

    // ── Bar creation ────────────────────────────────────────────────────────

    private HealthBarEntry CreateBar(ResourceNode node)
    {
        // World-space canvas
        var root = new GameObject($"HPBar_{node.name}");
        root.transform.SetParent(transform, false);
        root.transform.position = node.transform.position + Vector3.up * _heightOffset;

        var canvas = root.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        canvas.sortingOrder = 100;

        var scaler = root.AddComponent<CanvasScaler>();
        scaler.dynamicPixelsPerUnit = 10;

        var group = root.AddComponent<CanvasGroup>();
        group.alpha = 1f;

        // Size the canvas
        var rect = root.GetComponent<RectTransform>();
        rect.sizeDelta = new Vector2(_barWidth, _barHeight);

        // Slider
        var sliderObj = new GameObject("Slider");
        sliderObj.transform.SetParent(root.transform, false);
        var slider = sliderObj.AddComponent<Slider>();
        slider.interactable = false;
        slider.transition = Selectable.Transition.None;

        var sliderRect = sliderObj.GetComponent<RectTransform>();
        sliderRect.anchorMin = Vector2.zero;
        sliderRect.anchorMax = Vector2.one;
        sliderRect.offsetMin = Vector2.zero;
        sliderRect.offsetMax = Vector2.zero;

        // Background (dark bar)
        var bgObj = new GameObject("Background");
        bgObj.transform.SetParent(sliderObj.transform, false);
        var bgImage = bgObj.AddComponent<Image>();
        bgImage.color = new Color(0.1f, 0.1f, 0.1f, 0.8f);
        var bgRect = bgObj.GetComponent<RectTransform>();
        bgRect.anchorMin = Vector2.zero;
        bgRect.anchorMax = Vector2.one;
        bgRect.offsetMin = Vector2.zero;
        bgRect.offsetMax = Vector2.zero;
        slider.targetGraphic = bgImage;

        // Fill area
        var fillAreaObj = new GameObject("Fill Area");
        fillAreaObj.transform.SetParent(sliderObj.transform, false);
        var fillAreaRect = fillAreaObj.GetComponent<RectTransform>();
        fillAreaRect.anchorMin = Vector2.zero;
        fillAreaRect.anchorMax = Vector2.one;
        fillAreaRect.offsetMin = Vector2.zero;
        fillAreaRect.offsetMax = Vector2.zero;

        // Fill (white bar — Flynn mono palette)
        var fillObj = new GameObject("Fill");
        fillObj.transform.SetParent(fillAreaObj.transform, false);
        var fillImage = fillObj.AddComponent<Image>();
        fillImage.color = Color.white;
        var fillRect = fillObj.GetComponent<RectTransform>();
        fillRect.anchorMin = Vector2.zero;
        fillRect.anchorMax = Vector2.one;
        fillRect.offsetMin = Vector2.zero;
        fillRect.offsetMax = Vector2.zero;
        slider.fillRect = fillRect;

        // Handle area (none — clean bar)
        var handleAreaObj = new GameObject("Handle Slide Area");
        handleAreaObj.transform.SetParent(sliderObj.transform, false);
        var handleAreaRect = handleAreaObj.GetComponent<RectTransform>();
        handleAreaRect.anchorMin = Vector2.zero;
        handleAreaRect.anchorMax = Vector2.one;
        handleAreaRect.offsetMin = Vector2.zero;
        handleAreaRect.offsetMax = Vector2.zero;
        handleAreaObj.SetActive(false);

        slider.value = 1f;

        return new HealthBarEntry
        {
            Root = root,
            Canvas = canvas,
            Slider = slider,
            Group = group,
            HideTime = Time.time + _displayDuration,
            Fading = false,
        };
    }
}

args.contents:
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using Flynn.Events;

/// <summary>
/// Pools reusable world-space HP bars for ResourceNodes. Subscribes to
/// ResourceDamaged / ResourceDepleted on GameEventBus. A bar is acquired from
/// the pool on first hit, tracks the node each frame, and is released back
/// after fade-out or depletion. No per-node instantiation beyond the first
/// pool fill.
///
/// Bar style: white fill depleting left→right on a black background (Flynn mono).
/// One per scene under MANAGERS/UI.
/// </summary>
public class ResourceHealthBarManager : MonoBehaviour
{
    [Header("Bar Appearance")]
    [Tooltip("World-space height offset above the node origin.")]
    [SerializeField] private float _heightOffset = 1.4f;

    [Tooltip("Width of the slider bar in world units.")]
    [SerializeField] private float _barWidth = 1.2f;

    [Tooltip("Height of the slider bar in world units.")]
    [SerializeField] private float _barHeight = 0.12f;

    [Header("Pool")]
    [Tooltip("Number of pre-warmed bar instances.")]
    [SerializeField] private int _poolSize = 8;

    [Header("Timing")]
    [Tooltip("Seconds to keep the bar visible after the last hit.")]
    [SerializeField] private float _displayDuration = 3f;

    [Tooltip("Seconds for the fade-out animation.")]
    [SerializeField] private float _fadeDuration = 0.5f;

    // ── Pool & active tracking ─────────────────────────────────────────────

    private readonly Stack<HealthBar> _pool = new();
    private readonly Dictionary<ResourceNode, HealthBar> _active = new();

    private struct HealthBar
    {
        public GameObject Root;
        public Slider Slider;
        public CanvasGroup Group;
        public ResourceNode Node;     // current target (default = null)
        public float HideTime;
        public bool Fading;
    }

    // ── Unity messages ──────────────────────────────────────────────────────

    private void Awake()
    {
        for (int i = 0; i < _poolSize; i++)
            _pool.Push(CreateBar());
    }

    private void OnEnable()
    {
        GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
    }

    private void OnDisable()
    {
        if (GameEventBus.Instance == null) return;
        GameEventBus.Instance.Unsubscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Unsubscribe<ResourceDepleted>(OnResourceDepleted);
    }

    private void LateUpdate()
    {
        float now = Time.time;
        List<ResourceNode> toRelease = null;

        foreach (var kvp in _active)
        {
            var bar = kvp.Value;
            var node = kvp.Key;

            // Node destroyed — release immediately
            if (node == null)
            {
                if (toRelease == null) toRelease = new List<ResourceNode>();
                toRelease.Add(node);
                continue;
            }

            // Track position above node
            bar.Root.transform.position = node.transform.position + Vector3.up * _heightOffset;

            // Billboard toward camera
            if (Camera.main != null)
                bar.Root.transform.rotation = Camera.main.transform.rotation;

            // Start fading when timer expires
            if (!bar.Fading && now >= bar.HideTime)
                bar.Fading = true;

            // Animate fade
            if (bar.Fading)
            {
                float alpha = 1f - Mathf.Clamp01((now - bar.HideTime) / _fadeDuration);
                bar.Group.alpha = alpha;

                if (alpha <= 0f)
                {
                    if (toRelease == null) toRelease = new List<ResourceNode>();
                    toRelease.Add(node);
                }
            }
        }

        // Release finished bars back to pool
        if (toRelease != null)
        {
            foreach (var node in toRelease)
                ReleaseBar(node);
        }
    }

    // ── Event handlers ──────────────────────────────────────────────────────

    private void OnResourceDamaged(ResourceDamaged evt)
    {
        if (evt.Node == null) return;

        // Acquire a bar if this node doesn't have one yet
        if (!_active.TryGetValue(evt.Node, out var bar))
        {
            bar = AcquireBar(evt.Node);
            if (bar.Root == null) return; // pool exhausted
        }

        // Update fill — white bar shrinks as HP depletes, revealing black bg
        float ratio = evt.Node.MaxHealth > 0 ? (float)evt.RemainingHp / evt.Node.MaxHealth : 0f;
        bar.Slider.value = ratio;

        // Show and reset timer
        bar.Root.SetActive(true);
        bar.Group.alpha = 1f;
        bar.Fading = false;
        bar.HideTime = Time.time + _displayDuration;

        _active[evt.Node] = bar;
    }

    private void OnResourceDepleted(ResourceDepleted evt)
    {
        if (evt.Node == null) return;
        if (!_active.TryGetValue(evt.Node, out var bar)) return;

        // Snap fill to zero and start fade
        bar.Slider.value = 0f;
        bar.Fading = true;
        bar.HideTime = Time.time;
        _active[evt.Node] = bar;
    }

    // ── Pool acquire / release ──────────────────────────────────────────────

    private HealthBar AcquireBar(ResourceNode node)
    {
        HealthBar bar;
        if (_pool.Count > 0)
        {
            bar = _pool.Pop();
        }
        else
        {
            // Grow pool if needed
            bar = CreateBar();
        }

        bar.Node = node;
        bar.Slider.value = 1f;
        bar.Group.alpha = 1f;
        bar.Fading = false;
        bar.Root.name = $"HPBar_{node.name}";
        bar.Root.SetActive(true);
        _active[node] = bar;
        return bar;
    }

    private void ReleaseBar(ResourceNode node)
    {
        if (!_active.TryGetValue(node, out var bar)) return;

        bar.Root.SetActive(false);
        bar.Root.name = "HPBar_Pooled";
        bar.Node = null;
        bar.Fading = false;
        bar.Group.alpha = 1f;
        bar.Slider.value = 1f;

        _active.Remove(node);
        _pool.Push(bar);
    }

    // ── Bar factory ─────────────────────────────────────────────────────────

    private HealthBar CreateBar()
    {
        // World-space canvas
        var root = new GameObject("HPBar_Pooled");
        root.transform.SetParent(transform, false);
        root.SetActive(false);

        var canvas = root.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        canvas.sortingOrder = 100;

        root.AddComponent<CanvasScaler>().dynamicPixelsPerUnit = 10;

        var group = root.AddComponent<CanvasGroup>();

        var rootRect = root.GetComponent<RectTransform>();
        rootRect.sizeDelta = new Vector2(_barWidth, _barHeight);

        // ── Slider ──────────────────────────────────────────────────────────
        var sliderObj = new GameObject("Slider");
        sliderObj.transform.SetParent(root.transform, false);
        var slider = sliderObj.AddComponent<Slider>();
        slider.interactable = false;
        slider.transition = Selectable.Transition.None;
        slider.direction = Slider.Direction.LeftToRight;

        var sliderRect = sliderObj.GetComponent<RectTransform>();
        sliderRect.anchorMin = Vector2.zero;
        sliderRect.anchorMax = Vector2.one;
        sliderRect.offsetMin = Vector2.zero;
        sliderRect.offsetMax = Vector2.zero;

        // Background — solid black
        var bgObj = new GameObject("Background");
        bgObj.transform.SetParent(sliderObj.transform, false);
        var bgImage = bgObj.AddComponent<Image>();
        bgImage.color = Color.black;
        Stretch(bgObj);
        slider.targetGraphic = bgImage;

        // Fill area — stretches under the white fill
        var fillAreaObj = new GameObject("Fill Area");
        fillAreaObj.transform.SetParent(sliderObj.transform, false);
        Stretch(fillAreaObj);

        // Fill — white that shrinks as HP depletes, revealing black bg
        var fillObj = new GameObject("Fill");
        fillObj.transform.SetParent(fillAreaObj.transform, false);
        var fillImage = fillObj.AddComponent<Image>();
        fillImage.color = Color.white;
        Stretch(fillObj);
        slider.fillRect = fillObj.GetComponent<RectTransform>();

        // Handle area — disabled for a clean bar look
        var handleAreaObj = new GameObject("Handle Slide Area");
        handleAreaObj.transform.SetParent(sliderObj.transform, false);
        Stretch(handleAreaObj);
        handleAreaObj.SetActive(false);

        slider.value = 1f;

        return new HealthBar
        {
            Root = root,
            Slider = slider,
            Group = group,
            Node = null,
            HideTime = 0f,
            Fading = false,
        };
    }

    private static void Stretch(GameObject go)
    {
        var r = go.GetComponent<RectTransform>();
        r.anchorMin = Vector2.zero;
        r.anchorMax = Vector2.one;
        r.offsetMin = Vector2.zero;
        r.offsetMax = Vector2.zero;
    }
}

