// Clean up any leftover HPBar world-space canvas objects
var allTransforms = UnityEngine.Object.FindObjectsOfType<UnityEngine.Transform>();
int removed = 0;
foreach (var t in allTransforms)
{
    if (t.name.StartsWith("HPBar_") && t.parent != null && t.parent.name == "ResourceHP")
    {
        UnityEngine.Object.DestroyImmediate(t.gameObject);
        removed++;
    }
}
UnityEngine.Debug.Log($"[Cleanup] Removed {removed} orphan HPBar objects");

// Verify the UIDocument is set up
var doc = UnityEngine.Object.FindObjectOfType<ResourceHealthBarManager>()?.GetComponent<UnityEngine.UIElements.UIDocument>();
if (doc != null)
{
    UnityEngine.Debug.Log($"[Verify] UIDocument panelSettings: {(doc.panelSettings != null ? doc.panelSettings.name : "null")}");
    UnityEngine.Debug.Log($"[Verify] UIDocument visualTreeAsset: {(doc.visualTreeAsset != null ? doc.visualTreeAsset.name : "null")}");
}

