    var so = new UnityEditor.SerializedObject(panel);
    var prop = so.FindProperty("_panelId");
    if (prop != null)
    {
        prop.enumValueIndex = (int)UIPanelId.ResourceHP; // 6
        so.ApplyModifiedProperties();
        UnityEngine.Debug.Log($"[Setup] ResourceHPPanel _panelId set to ResourceHP ({prop.enumValueIndex})");
    }
    else
    {
        UnityEngine.Debug.LogError("[Setup] Could not find _panelId property");
    }

    // Register with UIManager
    var uiManager = UIManager.Instance;
    if (uiManager != null)
    {
        uiManager.Register(panel);
        UnityEngine.Debug.Log($"[Setup] ResourceHPPanel registered with UIManager");
    }
}

